#!/usr/bin/perl
# Ovrtone's icon set: writes one SVG per icon into ovrtone/. Run from this folder: perl make-icons.pl
#
# The style, for every icon (and for a designer's replacements, see ovrtone/README.md):
# a 24 x 24 grid, lines 1.75 wide with round ends and joins, and a soft second tone: closed,
# convex shapes marked data-tone="soft" are filled at about a third of the colour, behind the lines.
# data-tone="solid" shapes are filled fully (key tops, knobs, dots).
use strict;
use warnings;

sub c  { my ($x, $y, $r) = @_; my $d = 2 * $r; return "M" . ($x - $r) . " $y" . "a$r $r 0 1 0 $d 0a$r $r 0 1 0 -$d 0Z"; }
sub rr { my ($x, $y, $w, $h, $r) = @_;
    my ($iw, $ih) = ($w - 2 * $r, $h - 2 * $r);
    return "M" . ($x + $r) . " $y" . "h$iw" . "a$r $r 0 0 1 $r $r" . "v$ih" . "a$r $r 0 0 1 -$r $r" . "h-$iw" . "a$r $r 0 0 1 -$r -$r" . "v-$ih" . "a$r $r 0 0 1 $r -$r" . "Z"; }

