mkdir 'ovrtone' unless -d 'ovrtone';
for my $name (sort keys %icons) {
    my $body = '';
    # Fills first, so the lines draw on top of them.
    for my $part (sort { ($b->[0] ne '') <=> ($a->[0] ne '') } @{ $icons{$name} }) {
        my ($tone, $d) = @$part;
        if ($tone eq 'soft') {
            $body .= qq(  <path data-tone="soft" d="$d" fill="currentColor" fill-opacity=".32" stroke="none"/>\n);
        } elsif ($tone eq 'solid') {
            $body .= qq(  <path data-tone="solid" d="$d" fill="currentColor" stroke="none"/>\n);
        } else {
            $body .= qq(  <path d="$d"/>\n);
        }
    }
    open my $f, '>', "ovrtone/$name.svg" or die "$name: $!";
    print $f qq(<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round">\n$body</svg>\n);
    close $f;
}
print scalar(keys %icons), " icons\n";
